<script setup lang="ts">
import {collectionItems,resourceItem,useMediaUrl,type CmsEntry} from '~/composables/useBackend'
const slug=String(useRoute().params.id)
const {data,error,pending}=await useBackend().contentItem('posts',slug)
const {data:categoryResponse}=await useBackend().content('categories',{per_page:100})
const mediaUrl=useMediaUrl()
const post=computed(()=>resourceItem<CmsEntry>(data.value))
const categoryTitle=computed(()=>collectionItems<CmsEntry>(categoryResponse.value).find(item=>item.slug===post.value?.extra?.category_slug)?.title)
const shareUrl=ref(''),copied=ref(false)
const publishedDate=computed(()=>{const value=post.value?.extra?.published_at||post.value?.created_at;if(!value)return '';try{return new Intl.DateTimeFormat('fa-IR-u-ca-persian',{dateStyle:'long',timeZone:'Asia/Tehran'}).format(new Date(value))}catch{return ''}})
onMounted(()=>{shareUrl.value=window.location.href})
async function copyLink(){try{await navigator.clipboard.writeText(shareUrl.value);copied.value=true;setTimeout(()=>copied.value=false,2200)}catch{copied.value=false}}
const articleSchema=computed(()=>JSON.stringify({'@context':'https://schema.org','@type':'Article',headline:post.value?.title,...(post.value?.image?{image:mediaUrl(post.value.image)}:{}),...(post.value?.extra?.author?{author:{'@type':'Person',name:post.value.extra.author}}:{}),...(post.value?.extra?.published_at?{datePublished:post.value.extra.published_at}:{}),...(post.value?.extra?.updated_at?{dateModified:post.value.extra.updated_at}:{})}).replace(/</g,'\\u003c'))
useSeoMeta({title:()=>post.value?.extra?.seo_title||post.value?.title||'مقاله',description:()=>post.value?.extra?.seo_description||post.value?.body||'',ogTitle:()=>post.value?.title||'',ogDescription:()=>post.value?.extra?.seo_description||post.value?.body||'',ogImage:()=>post.value?.image?mediaUrl(post.value.image):undefined,ogType:'article',twitterCard:'summary_large_image'})
useHead({script:[{key:'article-jsonld',type:'application/ld+json',innerHTML:computed(()=>post.value?articleSchema.value:'')}]})
</script>
<template><article class="container article-page"><ApiNotice v-if="error && !pending">این مطلب در سامانه پیدا نشد.</ApiNotice><p v-else-if="pending">در حال بارگذاری…</p><template v-else-if="post"><nav class="article-breadcrumb"><NuxtLink to="/">خانه</NuxtLink><span aria-hidden="true">/</span><NuxtLink to="/blog">مجله آرامش</NuxtLink><span aria-hidden="true">/</span><span>{{post.title}}</span></nav><header class="article-header"><span v-if="post.extra?.category_slug" class="status-pill">{{categoryTitle||'مقاله'}}</span><h1>{{post.title}}</h1><div class="article-meta"><time v-if="publishedDate">{{publishedDate}}</time><span v-if="post.extra?.author">{{post.extra.author}}</span></div></header><img v-if="post.image" class="article-image" :src="mediaUrl(post.image)" :alt="post.title" fetchpriority="high"><div class="article-layout"><div class="preline article-body">{{post.body}}</div><aside class="article-aside"><strong>اشتراک‌گذاری مقاله</strong><button class="share-action" type="button" @click="copyLink">{{copied?'پیوند کپی شد':'کپی پیوند'}}</button><a v-if="shareUrl" class="share-action" :href="`https://t.me/share/url?url=${encodeURIComponent(shareUrl)}&text=${encodeURIComponent(post.title)}`" target="_blank" rel="noopener noreferrer">اشتراک در تلگرام</a><a v-if="shareUrl" class="share-action" :href="`https://wa.me/?text=${encodeURIComponent(post.title+' '+shareUrl)}`" target="_blank" rel="noopener noreferrer">اشتراک در واتس‌اپ</a><NuxtLink class="text-link" to="/blog">بازگشت به مقاله‌ها <ArrowIcon direction="back" /></NuxtLink></aside></div></template></article></template>
